/**
 * DICCIONARIO ES / EN — Sistema Restrepo Acosta Global Holding LLC
 * ─────────────────────────────────────────────────────────────────────────────
 * REGLAS DE ORO (leer antes de agregar una clave):
 *
 * 1. `es` es la FUENTE DE VERDAD. `en` está tipado como Record<TranslationKey,string>,
 *    así que si agregas una clave a `es` y olvidas su traducción, el build de
 *    TypeScript FALLA. Es imposible desplegar una traducción incompleta.
 *
 * 2. NUNCA traducir aquí: claves de API, enums de base de datos, códigos de fase,
 *    nombres propios ni identificadores. Solo texto que ve el usuario.
 *
 * 3. Terminología técnica del sector (draw, punch list, change order, holdback,
 *    net wire, ARV, $/SF, runway) se mantiene en inglés en AMBOS idiomas: es el
 *    vocabulario real que usan lenders y GCs en EE. UU. Traducirlo sería
 *    incorrecto, no "más español".
 *
 * 4. Plurales: definir `clave_one` y `clave_other` y usar tc(clave, n).
 *
 * 5. Interpolación: {{variable}} → t('clave', { variable: valor })
 */

